-- SQLite 3 pilot schema v1. No production government tables or model labels.
PRAGMA foreign_keys=ON;
CREATE TABLE publisher(publisher_id TEXT PRIMARY KEY,name TEXT NOT NULL,hq_country TEXT,hq_evidence_url TEXT,hq_verification TEXT NOT NULL);
CREATE TABLE outlet(source_id TEXT PRIMARY KEY,publisher_id TEXT NOT NULL REFERENCES publisher,outlet_name TEXT NOT NULL,outlet_type TEXT NOT NULL,editorial_identity_evidence TEXT,official_home TEXT NOT NULL);
CREATE TABLE edition(edition_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES outlet,region_layer TEXT NOT NULL CHECK(region_layer IN('EU_Europe','UK','AU','US','NZ')),edition_market TEXT NOT NULL,edition_market_evidence TEXT,edition_verification TEXT NOT NULL,region_assignment_basis TEXT NOT NULL);
CREATE TABLE source_era(era_id TEXT PRIMARY KEY,edition_id TEXT NOT NULL REFERENCES edition,month TEXT NOT NULL,medium TEXT NOT NULL,applicability TEXT NOT NULL,era_scope_note TEXT NOT NULL,route TEXT,rights_status TEXT NOT NULL,rights_evidence_url TEXT,access_status TEXT NOT NULL,access_entitlement TEXT,checked_at_utc TEXT,publisher_at_time TEXT,publisher_at_time_verification TEXT NOT NULL DEFAULT 'unknown; current owner must not be backdated',UNIQUE(edition_id,month));
CREATE TABLE frame(frame_id TEXT PRIMARY KEY,era_id TEXT NOT NULL REFERENCES source_era,provider TEXT NOT NULL,month TEXT NOT NULL,unit TEXT NOT NULL CHECK(unit='article_publication_instance'),date_filter_json TEXT NOT NULL,type_filter_json TEXT NOT NULL,topic_query TEXT CHECK(topic_query IS NULL),enumeration_state TEXT NOT NULL,visible_provider_count INTEGER,observed_unique_links INTEGER,monthly_denominator INTEGER,denominator_unit TEXT,count_evidence TEXT,page_limit INTEGER NOT NULL,visited_pages INTEGER NOT NULL DEFAULT 0,scope_detail TEXT NOT NULL,retrieval_at_utc TEXT, CHECK(monthly_denominator IS NULL OR (enumeration_state='complete_month_frame' AND monthly_denominator>=0)));
CREATE TABLE article_parent(parent_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES outlet,edition_id TEXT NOT NULL REFERENCES edition,native_id TEXT NOT NULL,native_id_basis TEXT NOT NULL,canonical_url TEXT NOT NULL,language TEXT,genre TEXT NOT NULL,publishing_role TEXT NOT NULL CHECK(publishing_role='media'),first_publication_value TEXT,first_date_precision TEXT NOT NULL,first_timezone TEXT,first_date_min TEXT,first_date_max TEXT,date_evidence TEXT,byline TEXT,author_geography_json TEXT,reported_places_json TEXT,identity_state TEXT NOT NULL,UNIQUE(source_id,native_id));
CREATE TABLE paper_issue(issue_id TEXT PRIMARY KEY,edition_id TEXT NOT NULL REFERENCES edition,issue_date_value TEXT,date_precision TEXT NOT NULL,volume TEXT,issue_number TEXT,issue_locator TEXT,evidence_url TEXT);
CREATE TABLE article_locator(locator_id TEXT PRIMARY KEY,parent_id TEXT NOT NULL REFERENCES article_parent,issue_id TEXT REFERENCES paper_issue,page_start TEXT,page_end TEXT,ocr_native_id TEXT,ocr_bbox_json TEXT,layout_status TEXT NOT NULL,boundary_status TEXT NOT NULL,locator_evidence TEXT);
CREATE TABLE raw_object(raw_id TEXT PRIMARY KEY,path TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,byte_count INTEGER NOT NULL CHECK(byte_count>=0),mime_type TEXT,object_kind TEXT NOT NULL,is_partial INTEGER NOT NULL CHECK(is_partial IN(0,1)),rights_status TEXT NOT NULL,redistribution_status TEXT NOT NULL,request_id TEXT,retained_at_utc TEXT NOT NULL);
CREATE TABLE article_version(version_id TEXT PRIMARY KEY,parent_id TEXT NOT NULL REFERENCES article_parent,raw_id TEXT REFERENCES raw_object,raw_publication_value TEXT,updated_value TEXT,updated_precision TEXT NOT NULL,content_version_time TEXT,content_time_precision TEXT NOT NULL,retrieved_at_utc TEXT NOT NULL,retrieval_precision TEXT NOT NULL,body_storage_path TEXT,body_sha256 TEXT,readability_status TEXT NOT NULL,preview_status TEXT NOT NULL,ocr_quality_status TEXT NOT NULL,layout_status TEXT NOT NULL,rights_status TEXT NOT NULL,access_status TEXT NOT NULL,extractor_version TEXT NOT NULL,version_evidence TEXT,UNIQUE(parent_id,raw_id,extractor_version));
CREATE TABLE frame_membership(frame_id TEXT NOT NULL REFERENCES frame,parent_id TEXT NOT NULL REFERENCES article_parent,index_url TEXT NOT NULL,index_occurrence_count INTEGER NOT NULL,identity_evidence TEXT,PRIMARY KEY(frame_id,parent_id,index_url));
CREATE TABLE story_cluster(story_id TEXT PRIMARY KEY,cluster_kind TEXT NOT NULL CHECK(cluster_kind IN('wire_story','syndication','mirror','unresolved_candidate')),origin_provider TEXT,origin_native_id TEXT,origin_first_date TEXT,verification_state TEXT NOT NULL,evidence TEXT NOT NULL);
CREATE TABLE publication_relationship(relation_id TEXT PRIMARY KEY,parent_id TEXT NOT NULL REFERENCES article_parent,related_parent_id TEXT REFERENCES article_parent,story_id TEXT REFERENCES story_cluster,relation_kind TEXT NOT NULL CHECK(relation_kind IN('wire_adoption','syndication','mirror','same_document_version','duplicate_index','unresolved_candidate')),verification_state TEXT NOT NULL,evidence TEXT NOT NULL,publication_instance_retained INTEGER NOT NULL CHECK(publication_instance_retained=1));
CREATE TABLE attributed_voice(voice_id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES article_version,voice_kind TEXT NOT NULL CHECK(voice_kind IN('byline','quoted_speaker','reader_letter_author','editorial_voice','unknown')),speaker_name TEXT,speaker_role TEXT,speaker_geography_json TEXT,quotation_locator TEXT,attribution_state TEXT NOT NULL,quotation_and_publishing_role_separate INTEGER NOT NULL CHECK(quotation_and_publishing_role_separate=1));
CREATE TABLE provenance_assertion(assertion_id TEXT PRIMARY KEY,parent_id TEXT NOT NULL REFERENCES article_parent,version_id TEXT REFERENCES article_version,provenance_class TEXT NOT NULL CHECK(provenance_class IN('direct_original','archival_reproduction','indirect_secondary','mixed','unresolved')),identity_verification TEXT NOT NULL,date_mapping_verification TEXT NOT NULL,content_mapping_verification TEXT NOT NULL,conflict_note TEXT,access_limit TEXT,evidence_locator TEXT NOT NULL,verified_at_utc TEXT,truth_of_reported_claims_assessed INTEGER NOT NULL DEFAULT 0 CHECK(truth_of_reported_claims_assessed=0));
CREATE TABLE sample_slot(slot_id TEXT PRIMARY KEY,frame_id TEXT NOT NULL REFERENCES frame,slot_index INTEGER NOT NULL CHECK(slot_index BETWEEN 1 AND 5),parent_id TEXT REFERENCES article_parent,status TEXT NOT NULL,unfilled_reason TEXT,selection_design TEXT NOT NULL,pi REAL CHECK(pi IS NULL OR (pi>0 AND pi<=1)),pi_basis TEXT,planned_region_weight REAL NOT NULL,planned_source_within_region_weight REAL NOT NULL,observed_inventory_weight REAL NOT NULL DEFAULT 1,UNIQUE(frame_id,slot_index),CHECK(pi IS NULL OR (pi_basis IS NOT NULL AND selection_design='probability_sample_complete_frame')));
CREATE TRIGGER pi_requires_complete_frame BEFORE INSERT ON sample_slot WHEN NEW.pi IS NOT NULL BEGIN SELECT CASE WHEN (SELECT enumeration_state FROM frame WHERE frame_id=NEW.frame_id)!='complete_month_frame' THEN RAISE(ABORT,'pi requires a complete declared frame') END; END;
CREATE TRIGGER pi_update_requires_complete_frame BEFORE UPDATE ON sample_slot WHEN NEW.pi IS NOT NULL BEGIN SELECT CASE WHEN (SELECT enumeration_state FROM frame WHERE frame_id=NEW.frame_id)!='complete_month_frame' THEN RAISE(ABORT,'pi requires a complete declared frame') END; END;
CREATE TRIGGER frame_cannot_invalidate_pi BEFORE UPDATE ON frame WHEN NEW.enumeration_state!='complete_month_frame' AND EXISTS(SELECT 1 FROM sample_slot WHERE frame_id=OLD.frame_id AND pi IS NOT NULL) BEGIN SELECT RAISE(ABORT,'clear or revalidate pi before changing frame completeness'); END;
CREATE TABLE request_attempt(request_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES outlet,purpose TEXT NOT NULL,request_url TEXT NOT NULL,requested_at_utc TEXT NOT NULL,finished_at_utc TEXT,http_status INTEGER,status TEXT NOT NULL,final_url TEXT,response_headers_json TEXT,raw_id TEXT REFERENCES raw_object,error TEXT,retry_not_before_utc TEXT,transport TEXT NOT NULL);
CREATE TABLE legacy_diagnostic(diagnostic_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES outlet,parent_url TEXT NOT NULL,original_publication_value TEXT,content_hash_receipt TEXT,evidence_path TEXT NOT NULL,evidence_sha256 TEXT NOT NULL,original_scope TEXT NOT NULL,current_pilot_slot_eligible INTEGER NOT NULL CHECK(current_pilot_slot_eligible=0),full_body_locally_retained INTEGER NOT NULL CHECK(full_body_locally_retained=0),diagnostic_note TEXT NOT NULL);
